// Prépare chaque email : expéditeur, objet, texte (sans l'historique cité), liens.
const out = [];
for (const item of $input.all()) {
  const e = item.json;
  const from = e.from?.value?.[0] ?? {};
  const to = e.to?.value?.[0]?.address ?? null;
  const html = e.html || '';
  let text = e.text || html.replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
  text = text.replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').trim();

  // on coupe l'historique cité (« Le … a écrit : », « On … wrote: », « De : … »)
  const cut = text.search(/\n\s*(Le .{5,120}a écrit\s*:|On .{5,120}wrote:|-{2,}\s*Original Message|-{2,}\s*Message d'origine|De\s*:.*\n\s*(Envoyé|Date)\s*:)/i);
  const reply = (cut > 20 ? text.slice(0, cut) : text).trim();

  // liens de l'email (utile pour retrouver la conversation sur Codeur, Fiverr, Malt…)
  const links = [...new Set([...html.matchAll(/href=["'](https?:\/\/[^"'\s>]+)["']/gi)].map((m) => m[1]))]
    .filter((u) => !/unsubscribe|desinscri|désinscri|optout|tracking-pixel|\.(png|jpe?g|gif)(\?|$)/i.test(u))
    .slice(0, 15);

  const email = {
    external_id: e.id,
    thread_id: e.threadId,
    from_email: (from.address || '').toLowerCase(),
    from_name: from.name || null,
    to_email: to,
    subject: e.subject || '',
    body: reply.slice(0, 20000),
    received_at: e.date || new Date().toISOString(),
  };

  const prompt = `Trie cet email reçu sur l'adresse pro.

RÈGLES
- "client" : une vraie personne ou entreprise qui écrit directement : réponse à un email de prospection, demande de devis, question, client existant.
- "plateforme" : notification d'une plateforme de freelance (Codeur, Fiverr, Malt, ComeUp, 5euros, Upwork, LinkedIn…) qui annonce un NOUVEAU projet, une demande ou un message d'un client. Récupère le nom du client, le projet, le budget et le lien vers la conversation ou le projet (platform_url : le lien du bouton « Voir le message », « Répondre » ou « Voir le projet », choisi dans la liste de liens). Une notification de plateforme sans client (newsletter, paiement reçu, facture, conseil) = "autre".
- "autre" : newsletters, factures, banque, réseaux sociaux, Google, confirmations, notifications automatiques. Les notifications du formulaire du site solvelab.fr et de Cal.com sont DÉJÀ dans le CRM : "autre".
- verdict "spam" : démarchage de masse (SEO, backlinks, nom de domaine, crypto, « dear sir »), phishing, arnaque, robot. verdict "a_verifier" si tu hésites entre vraie demande et spam. Sinon "ok".
- classement (seulement si category = "client", sinon null) : "chaud" (intéressé, veut un devis, un RDV, pose des questions, nouvelle demande), "a_relancer" (pas maintenant, plus tard : mets relance_le), "pas_interesse", "stop" (demande de ne plus être contacté ou de se désinscrire).
- N'invente rien : null si l'info n'est pas dans l'email.

Réponds UNIQUEMENT avec ce JSON :
{"category":"client|plateforme|autre","verdict":"ok|a_verifier|spam","source":"email|codeur|fiverr|malt|comeup|5euros|upwork|linkedin|autre_plateforme","classement":"chaud|a_relancer|pas_interesse|stop|null","relance_le":"AAAA-MM-JJ ou null","resume":"une phrase courte en français","platform_url":"lien ou null","lead":{"company_name":null,"contact_name":null,"email":null,"phone":null,"city":null,"interest":null,"budget":null}}

EMAIL
De : ${email.from_name || ''} <${email.from_email}>
Objet : ${email.subject}
Texte :
${reply.slice(0, 6000)}

Liens trouvés :
${links.join('\n') || '(aucun)'}`;

  out.push({ json: {
    email,
    anthropic_body: {
      model: 'claude-haiku-5-5',
      max_tokens: 700,
      system: "Tu tries la boîte mail pro de SolveLab, agence digitale à Caen (sites internet, automatisation et IA, outils sur mesure, pub vidéo). Tu réponds uniquement avec un objet JSON valide, sans aucun texte autour.",
      messages: [{ role: 'user', content: prompt }],
    },
  }, pairedItem: item.pairedItem ?? { item: out.length } });
}
return out;

// Lit la réponse de l'IA et prépare l'envoi au CRM.
const prepared = $('Préparer l\'email').all();
return $input.all().map((item, i) => {
  const email = prepared[i]?.json.email ?? {};
  let ai = null;
  try {
    const raw = (item.json.content ?? []).map((c) => c.text ?? '').join('').trim();
    const json = raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1);
    ai = JSON.parse(json);
  } catch (e) { ai = null; }

  const nul = (v) => (v === 'null' || v === '' || v === undefined ? null : v);
  if (!ai) {
    return { json: { ...email, category: 'client', verdict: 'a_verifier', source: 'email', ai_summary: "L'IA n'a pas pu trier cet email : à vérifier." } };
  }
  const lead = Object.fromEntries(Object.entries(ai.lead ?? {}).map(([k, v]) => [k, nul(v)]));
  return { json: {
    ...email,
    category: ai.category,
    verdict: ai.verdict,
    source: ai.category === 'plateforme' ? (nul(ai.source) ?? 'plateforme') : 'email',
    classement: nul(ai.classement),
    relance_le: nul(ai.relance_le),
    ai_summary: nul(ai.resume),
    platform_url: nul(ai.platform_url),
    lead,
  } };
});
